@@ -722,6 +894,10 @@ std::vector<StmtPtr> RewriteDeadYieldSlotsOnce(const std::vector<StmtPtr>& stmts
     } else if (auto while_stmt = std::dynamic_pointer_cast<const WhileStmt>(stmt)) {
